// The brands' own logos, in app/static/logos/ (sources and terms: app/static/logos/SOURCES.md). "dark" is
// the brand's version for dark backgrounds, shown on a dark tile in the dark theme; a logo without one
// stays on a light tile in both themes, so its colours stay true.
// "fill": an app icon with its own margin, drawn to the edges of the tile.
const LOGOS = {
  googlegemini: { title: "Google Gemini", file: "googlegemini.svg" },  // vector, from LobeHub
  assemblyai: { title: "AssemblyAI", file: "assemblyai.svg" },  // its blue product mark, from LobeHub
  azure: { title: "Azure AI Speech", file: "azure.svg" },  // the Speech services icon of the Azure icon set
  openai: { title: "OpenAI", file: "openai.svg" },
  speechmatics: { title: "Speechmatics", file: "speechmatics.png", fill: true },  // an app icon, with its own margin
  cohere: { title: "Cohere", file: "cohere.svg" },  // vector, from LobeHub
  elevenlabs: { title: "ElevenLabs", file: "elevenlabs.svg", fill: true },
  deepgram: { title: "Deepgram", file: "deepgram.svg" },
  mistralai: { title: "Mistral AI", file: "mistralai.svg", dark: "mistralai.svg" },  // its gradient is made for both
  huggingface: { title: "Hugging Face", file: "huggingface.svg" },
  qwen: { title: "Qwen", file: "qwen.svg" },  // vector, from LobeHub
  meta: { title: "Meta", file: "meta.svg", dark: "meta.svg" },  // the same symbol on Meta's dark lockup
  fedora: { title: "Fedora", file: "fedora.svg" },
  debian: { title: "Debian", file: "debian.svg" },
  nvidia: { title: "NVIDIA", file: "nvidia.svg" },  // from LobeHub
  alibabacloud: { title: "Alibaba Cloud", file: "alibabacloud.svg" },  // from LobeHub
  groq: { title: "Groq", file: "groq.svg", dark: "groq-dark.svg" },
  intel: { title: "Intel", file: "intel.svg", wide: true },  // wordmarks: most of the tile's width
  amd: { title: "AMD", file: "amd.svg", wide: true },
  hp: { title: "HP", file: "hp.svg" },
  dell: { title: "Dell", file: "dell.svg", wide: true },
  lenovo: { title: "Lenovo", file: "lenovo.svg", wide: true },  // a wordmark: the whole width of the tile
  huawei: { title: "Huawei", file: "huawei.svg" },
  kubuntu: { title: "Kubuntu", file: "kubuntu.svg" },
  ubuntu: { title: "Ubuntu", file: "ubuntu.svg" },
  windows11: { title: "Windows", file: "windows11.svg" },
  windows10: { title: "Windows", file: "windows10.svg" },
};
const logoSrc = (file) => `/static/logos/${file}`;
const brandTitle = (slug) => (LOGOS[slug] || BRANDS[slug] || {}).title || slug;

// The names that point to each brand, matched case-insensitively ("12th Gen Intel(R) Core(TM)" -> intel,
// "NVIDIA RTX A1000" and "GeForce RTX 3050" -> nvidia, "LENOVO" -> lenovo, "Ubuntu 24.04" -> ubuntu).
const BRAND_NAMES = [
  ["intel", /\bintel\b/i],
  ["nvidia", /\b(nvidia|geforce|quadro|rtx|gtx)\b/i],
  ["amd", /\b(amd|radeon|ryzen|athlon|epyc|threadripper)\b/i],
  ["apple", /\b(apple|macos|macbook\w*|imac\w*)\b/i],
  ["qualcomm", /\b(qualcomm|snapdragon)\b/i],
  ["arm", /\b(arm|armv\d\w*|arm64|aarch64|cortex)\b/i],
  ["lenovo", /\blenovo\b/i],
  ["huawei", /\bhuawei\b/i],
  ["dell", /\bdell\b/i],
  ["hp", /\b(hp|hewlett-packard)\b/i],
  ["asus", /\basus(tek)?\b/i],
  ["acer", /\bacer\b/i],
  ["msi", /\b(msi|micro-star)\b/i],
  ["samsung", /\bsamsung\b/i],
  ["lg", /\blg\b/i],
  ["ubuntu", /\bubuntu\b/i],
  ["windows10", /\bwindows 10\b/i],
  // Windows 11, and any later or unnamed version
  ["windows11", /\bwindows(?! 10\b)\b/i],
  ["archlinux", /\barch linux\b/i],
  ["linuxmint", /\blinux mint\b/i],
  ["popos", /\bpop!_os\b/i],
  ["manjaro", /\bmanjaro\b/i],
  ["opensuse", /\bopensuse\b/i],
  ["kubuntu", /\bkubuntu\b/i],
  ["kdeneon", /\bkde neon\b/i],
  ["kdeplasma", /\b(kde|plasma)\b/i],
  ["gnome", /\bgnome\b/i],
  ["xfce", /\bxfce\b/i],
  // models and the services that run them
  ["elevenlabs", /\belevenlabs\b/i],
  ["deepgram", /\bdeepgram\b/i],
  ["googlegemini", /\bgemini\b/i],
  ["groq", /\bgroq\b/i],
  ["mistralai", /\b(mistral|voxtral)\b/i],
  ["qwen", /\bqwen\d*/i],
  ["meta", /\b(meta|facebook|omnilingual)\b/i],
  ["alibabacloud", /\b(alibaba|sensevoice|funaudiollm|paraformer)\b/i],
  ["huggingface", /\b(hugging ?face|hf\.co)\b/i],
  ["vulkan", /\bvulkan\b/i],
  // brands with a logo file only (LOGOS)
  ["fedora", /\bfedora\b/i],
  ["debian", /\bdebian\b/i],
  ["openai", /\bopenai\b/i],
  ["assemblyai", /\bassembly ?ai\b/i],
  ["azure", /\bazure\b/i],
  ["speechmatics", /\bspeechmatics\b/i],
  ["cohere", /\bcohere(labs)?\b/i],
];

// The brands named in a text, in the order they appear ("Intel Iris Xe Graphics (Vulkan)" -> intel, vulkan).
function brandsFor(text) {
  const found = [];
  for (const [slug, re] of BRAND_NAMES) {
    const m = re.exec(String(text || ""));
    if (m) found.push([m.index, slug]);
  }
  return found.sort((a, b) => a[0] - b[0]).map(([, slug]) => slug);
}
const brandFor = (text) => brandsFor(text)[0] || null;

// A brand colour is used where it stands out at least 3:1 from the panel (--surface in each theme);
// otherwise the logo takes the colour of the text around it (the plain-light / plain-dark classes).
const SURFACES = { light: "ffffff", dark: "161a20" };
function luminance(hex) {
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

// Inline logos for the brands named in a text, at the size of the text, titled with the brand's name.
function brandIcons(text) {
  return brandsFor(text).map((slug) => {
    const title = brandTitle(slug);
    if (LOGOS[slug]) return `<img class="vendor" src="${logoSrc(LOGOS[slug].file)}" alt="${title}" title="${title}">`;
    const { hex, path } = BRANDS[slug];
    const plain = Object.keys(SURFACES).filter((t) => contrast(hex, SURFACES[t]) < 3).map((t) => ` plain-${t}`).join("");
    return `<svg class="vendor${plain}" viewBox="0 0 24 24" role="img" aria-label="${title}" style="--brand:#${hex}"><title>${title}</title><path d="${path}"/></svg>`;
  }).join("");
}
